ini_set('display_errors',0); error_reporting(E_ALL); require_once __DIR__.'/config.php'; header('Content-Type: application/json; charset=utf-8');
function sb($m,$ep,$p=null,$timeout=90){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>$timeout]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);$h=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ['ok'=>$h>=200&&$h<300,'http'=>$h,'body'=>$b,'data'=>is_array($d)?$d:[]];}
function n($s){return strtolower(trim(preg_replace('/[^a-z0-9]+/i',' ',(string)$s)));}
function keyaddr($s){$s=strtolower((string)$s);$s=preg_replace('/\b(street|st|road|rd|avenue|ave|lane|ln|drive|dr|court|ct|place|pl|circle|cir|boulevard|blvd)\b/','',$s);return preg_replace('/[^a-z0-9]/','',$s);}
function v($row,$keys){foreach($keys as $k){foreach($row as $rk=>$val){if(n($rk)===n($k)&&trim((string)$val)!=='')return trim((string)$val);}}return '';}
function money($v){return (float)preg_replace('/[^0-9.]/','',(string)$v);}
function d($v){$t=strtotime((string)$v);return $t?date('Y-m-d',$t):null;}
function score($r){$s=55;$st=strtoupper($r['failed_status']??'');$dom=(int)($r['days_on_market']??0);$price=(float)($r['list_price']??0);if(str_contains($st,'EXP'))$s+=15;if(str_contains($st,'WITH'))$s+=12;if(str_contains($st,'CANC'))$s+=10;if($dom>=90)$s+=8;if($dom>=180)$s+=8;if($price>=700000)$s+=6;if($price>=1200000)$s+=8;if(!empty($r['owner_name']))$s+=5;return min(100,$s);}
function rec($row,$dataset,$batch){$sn=v($row,['Street Number']);$st=v($row,['Street Name']);$addr=v($row,['Address','Property Address','Street Address','Listing Address','Full Address']);if(!$addr&&($sn||$st))$addr=trim($sn.' '.$st);$town=v($row,['City','Town','Municipality']);$base=['import_batch'=>$batch,'address'=>$addr,'town'=>$town,'state'=>v($row,['State']),'county'=>v($row,['County']),'zip_code'=>v($row,['Zip Code','Zip']),'subdivision'=>v($row,['Subdivision','Subdivision/Complex']),'list_price'=>money(v($row,['List Price','Price','Last List Price'])),'close_price'=>money(v($row,['Close Price','Sold Price'])),'close_date'=>d(v($row,['Close Date','Closed Date','Sold Date'])),'owner_name'=>v($row,['Owner Name']),'bedrooms'=>money(v($row,['Beds Total','Bedrooms','Beds'])),'bathrooms'=>money(v($row,['Baths Total','Bathrooms','Baths'])),'sqft'=>money(v($row,['Sq Ft Total','SQFT Est Heated Above Grade','SqFt','Square Feet'])),'year_built'=>(int)money(v($row,['Year Built'])),'acres'=>money(v($row,['Acres'])),'property_tax'=>money(v($row,['Property Tax','Tax','Taxes'])),'tax_year'=>v($row,['Tax Year Pub Record','Tax Year']),'assessed_value'=>money(v($row,['Assessed Value'])),'mls_number'=>v($row,['MLS Number','MLS #']),'parcel_number'=>v($row,['Parcel Number']),'remarks'=>v($row,['Remarks - Public','Public Remarks','Remarks','Description']),'raw'=>$row,'normalized_address'=>keyaddr($addr),'created_at'=>date('c'),'updated_at'=>date('c')];if($dataset==='failed'){$base['source_name']='MLS Failed Export';$base['failed_status']=v($row,['Status','Last Status','Listing Status']);$base['original_price']=money(v($row,['Original List Price','Original Price']));$base['expiration_date']=d(v($row,['Expiration Date','Expired Date']));$base['status_change_date']=d(v($row,['Status Change Timestamp','Status Change Date']));$base['list_date']=d(v($row,['Start Marketing Date','List Date','Listing Date']));$base['days_on_market']=(int)money(v($row,['DOM','Days On Market','CDOM']));$base['list_agent']=v($row,['List Agent Full Name','Listing Agent','Agent']);$base['list_office']=v($row,['List Office Name','Listing Office','Office']);$base['opportunity_score']=score($base);$base['jessica_reason']='Failed listing source. Requires closed/active/pending match check.';}else{$base['source_name']='MLS '.ucfirst($dataset).' Export';$base['status_type']=$dataset;$base['status']=v($row,['Status','Listing Status']);}return $base;}
try{$in=json_decode(file_get_contents('php://input'),true);if(!is_array($in))$in=$_POST;$key=$in['key']??'';if(!defined('AFTER_HOURS_CRON_KEY')||!hash_equals(AFTER_HOURS_CRON_KEY,$key)){http_response_code(403);echo json_encode(['success'=>false,'error'=>'Invalid key']);exit;}$dataset=$in['dataset']??'failed';$batch=$in['batch']??($dataset.'_'.date('Ymd_His'));$replace=$in['replace']??'no';$idx=(int)($in['chunk_index']??0);if($idx===0&&$replace==='all'){if($dataset==='failed')sb('DELETE','mls_failed_records?id=not.is.null',null,120);else sb('DELETE','mls_status_records?status_type=eq.'.rawurlencode($dataset),null,120);}if($idx===0&&$replace==='batch'){if($dataset==='failed')sb('DELETE','mls_failed_records?import_batch=eq.'.rawurlencode($batch),null,120);else sb('DELETE','mls_status_records?import_batch=eq.'.rawurlencode($batch),null,120);}$payload=[];foreach(($in['rows']??[]) as $row){if(!is_array($row))continue;$r=rec($row,$dataset,$batch);if(!$r['address'])continue;$payload[]=$r;}if(!$payload){echo json_encode(['success'=>true,'inserted'=>0,'dataset'=>$dataset]);exit;}$table=$dataset==='failed'?'mls_failed_records':'mls_status_records';$res=sb('POST',$table,$payload,120);if(!$res['ok']){http_response_code(500);echo json_encode(['success'=>false,'error'=>'Insert failed','details'=>$res['body'],'dataset'=>$dataset,'chunk_index'=>$idx],JSON_PRETTY_PRINT);exit;}echo json_encode(['success'=>true,'dataset'=>$dataset,'chunk_index'=>$idx,'inserted'=>count($payload),'batch'=>$batch],JSON_PRETTY_PRINT);}catch(Throwable $e){http_response_code(500);echo json_encode(['success'=>false,'error'=>$e->getMessage(),'line'=>$e->getLine()],JSON_PRETTY_PRINT);}
